#include <bits/stdc++.h>
using namespace std;

vector<int> primeFactors(int value) {
    vector<int> factors;
    for (int p = 2; p * p <= value; ++p) {
        if (value % p != 0) continue;
        factors.push_back(p);
        while (value % p == 0) value /= p;
    }
    if (value > 1) factors.push_back(value);
    return factors;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int> nums;
    int value;
    while (cin >> value) nums.push_back(value);
    const int n = static_cast<int>(nums.size());
    if (n == 0) {
        cout << "false\n";
        return 0;
    }

    vector<char> visited(n, false);
    queue<int> pending;
    visited[0] = true;
    pending.push(0);
    while (!pending.empty()) {
        int index = pending.front();
        pending.pop();
        if (index == n - 1) {
            cout << "true\n";
            return 0;
        }
        for (int factor : primeFactors(nums[index])) {
            for (int next : {index - factor, index + factor}) {
                if (next >= 0 && next < n && !visited[next]) {
                    visited[next] = true;
                    pending.push(next);
                }
            }
        }
    }
    cout << "false\n";
    return 0;
}

