#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    getline(cin, line);
    stringstream parser(line);
    vector<long long> cost;
    long long value;
    while (parser >> value) cost.push_back(value);
    int k, maxSkip;
    cin >> k >> maxSkip;
    int n = static_cast<int>(cost.size());

    if (k == 0) {
        cout << (n <= maxSkip ? 0 : -1) << '\n';
        return 0;
    }
    if (k > n) {
        cout << -1 << '\n';
        return 0;
    }

    const long long INF = (1LL << 60);
    vector<long long> previous(n, INF), current(n, INF);
    for (int i = 0; i < n && i <= maxSkip; ++i) previous[i] = cost[i];

    for (int selected = 2; selected <= k; ++selected) {
        fill(current.begin(), current.end(), INF);
        deque<int> candidates;
        for (int i = 0; i < n; ++i) {
            int add = i - 1;
            if (add >= 0 && previous[add] < INF) {
                while (!candidates.empty() && previous[candidates.back()] >= previous[add]) {
                    candidates.pop_back();
                }
                candidates.push_back(add);
            }
            int firstAllowed = i - maxSkip - 1;
            while (!candidates.empty() && candidates.front() < firstAllowed) candidates.pop_front();
            if (!candidates.empty()) current[i] = previous[candidates.front()] + cost[i];
        }
        previous.swap(current);
    }

    long long answer = INF;
    int firstLast = max(0, n - 1 - maxSkip);
    for (int i = firstLast; i < n; ++i) answer = min(answer, previous[i]);
    cout << (answer == INF ? -1 : answer) << '\n';
    return 0;
}

