#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, gap, low, high;
    cin >> n >> k >> gap >> low >> high;
    vector<int> difficulty(n + 1);
    for (int i = 1; i <= n; ++i) cin >> difficulty[i];

    long long total = 0;
    vector<vector<int>> firstThree;
    vector<int> chosen;

    function<void(int, int)> search = [&](int nextIndex, int sum) {
        if (static_cast<int>(chosen.size()) == k) {
            if (sum >= low && sum <= high) {
                ++total;
                if (firstThree.size() < 3) firstThree.push_back(chosen);
            }
            return;
        }
        if (sum > high) return;
        int needed = k - static_cast<int>(chosen.size());
        for (int index = nextIndex; index <= n; ++index) {
            int remainingSpan = n - index;
            if (needed > 1 && remainingSpan < (needed - 1) * (gap + 1)) break;
            chosen.push_back(index);
            search(index + gap + 1, sum + difficulty[index]);
            chosen.pop_back();
        }
    };

    search(1, 0);
    cout << total << '\n';
    for (const auto& combination : firstThree) {
        for (int i = 0; i < static_cast<int>(combination.size()); ++i) {
            if (i) cout << ' ';
            cout << combination[i];
        }
        cout << '\n';
    }
    return 0;
}

