#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long budget;
    cin >> n >> budget;
    vector<long long> importance(n), memory(n);
    for (long long& value : importance) cin >> value;
    for (long long& value : memory) cin >> value;

    long long ordinary = 0, windowMemory = 0, windowScore = 0;
    int left = 0;
    for (int right = 0; right < n; ++right) {
        windowMemory += memory[right];
        windowScore += importance[right];
        while (left <= right && windowMemory > budget) {
            windowMemory -= memory[left];
            windowScore -= importance[left++];
        }
        ordinary = max(ordinary, windowScore);
    }

    long long quantized = ordinary;
    windowMemory = windowScore = 0;
    left = 0;
    deque<int> minimum;
    auto notBetter = [&](int oldIndex, int newIndex) {
        if (importance[oldIndex] != importance[newIndex]) {
            return importance[oldIndex] > importance[newIndex];
        }
        return memory[oldIndex] <= memory[newIndex];
    };

    for (int right = 0; right < n; ++right) {
        windowMemory += memory[right];
        windowScore += importance[right];
        while (!minimum.empty() && notBetter(minimum.back(), right)) minimum.pop_back();
        minimum.push_back(right);

        auto effectiveMemory = [&]() -> long long {
            if (minimum.empty()) return windowMemory;
            int chosen = minimum.front();
            return windowMemory - (memory[chosen] + 1) / 2;
        };
        while (left <= right && effectiveMemory() > budget) {
            if (!minimum.empty() && minimum.front() == left) minimum.pop_front();
            windowMemory -= memory[left];
            windowScore -= importance[left];
            ++left;
        }
        if (left <= right && !minimum.empty()) {
            quantized = max(quantized, windowScore - importance[minimum.front()]);
        }
    }

    cout << ordinary << ' ' << quantized << '\n';
    return 0;
}

