#include <bits/stdc++.h>
using namespace std;

struct DisjointSet {
    vector<int> parent, size;
    explicit DisjointSet(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, queryCount, minPoints;
    long double epsilon;
    cin >> n >> queryCount >> epsilon >> minPoints;
    vector<long double> x(n), y(n);
    for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];

    long double limit = epsilon * epsilon;
    vector<vector<char>> near(n, vector<char>(n, false));
    vector<int> neighborCount(n, 0);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long double dx = x[i] - x[j], dy = y[i] - y[j];
            if (dx * dx + dy * dy <= limit + 1e-12L) {
                near[i][j] = true;
                ++neighborCount[i];
            }
        }
    }

    vector<char> core(n, false);
    for (int i = 0; i < n; ++i) core[i] = neighborCount[i] >= minPoints;
    DisjointSet components(n);
    for (int i = 0; i < n; ++i) {
        if (!core[i]) continue;
        for (int j = i + 1; j < n; ++j) {
            if (core[j] && near[i][j]) components.unite(i, j);
        }
    }

    vector<vector<int>> memberships(n);
    for (int point = 0; point < n; ++point) {
        for (int candidate = 0; candidate < n; ++candidate) {
            if (core[candidate] && near[point][candidate]) {
                memberships[point].push_back(components.find(candidate));
            }
        }
        sort(memberships[point].begin(), memberships[point].end());
        memberships[point].erase(unique(memberships[point].begin(), memberships[point].end()), memberships[point].end());
    }

    while (queryCount--) {
        int first, second;
        cin >> first >> second;
        bool connected = false;
        for (int root : memberships[first]) {
            if (binary_search(memberships[second].begin(), memberships[second].end(), root)) {
                connected = true;
                break;
            }
        }
        cout << (connected ? 1 : 0) << '\n';
    }
    return 0;
}
